Schema:
CREATE TABLE branches (
  id INTEGER PRIMARY KEY, name TEXT NOT NULL, city TEXT NOT NULL, opened_at TEXT NOT NULL);
/* 3 sample rows of branches:
id | name | city | opened_at
1 | Mây Nguyễn Huệ | Hồ Chí Minh | 2024-03-01
2 | Mây Thảo Điền | Hồ Chí Minh | 2024-09-15
3 | Mây Phú Nhuận | Hồ Chí Minh | 2025-06-01 */
CREATE TABLE products (
  id INTEGER PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, price INTEGER NOT NULL, is_active INTEGER NOT NULL);
/* 3 sample rows of products:
id | name | category | price | is_active
1 | Trà sữa trân châu | trà sữa | 35000 | 1
2 | Trà sữa matcha | trà sữa | 42000 | 1
3 | Trà sữa khoai môn | trà sữa | 39000 | 1 */
CREATE TABLE customers (
  id INTEGER PRIMARY KEY, full_name TEXT NOT NULL, city TEXT NOT NULL, tier TEXT NOT NULL, joined_at TEXT NOT NULL);
/* 3 sample rows of customers:
id | full_name | city | tier | joined_at
1 | Đặng Thị Vy | Hồ Chí Minh | member | 2024-05-01 00:00:00
2 | Đặng Gia Thảo | Đà Nẵng | member | 2026-07-05 00:00:00
3 | Võ Bảo Hạnh | Hồ Chí Minh | silver | 2025-07-14 00:00:00 */
CREATE TABLE staff (
  id INTEGER PRIMARY KEY, full_name TEXT NOT NULL, branch_id INTEGER NOT NULL REFERENCES branches(id), role TEXT NOT NULL);
/* 3 sample rows of staff:
id | full_name | branch_id | role
1 | Nguyễn Thanh Sơn | 1 | quản lý
2 | Ngô Thị Minh | 1 | pha chế
3 | Nguyễn Hoàng Quân | 1 | pha chế */
CREATE TABLE orders (
  id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id), branch_id INTEGER NOT NULL REFERENCES branches(id),
  staff_id INTEGER REFERENCES staff(id), ordered_at TEXT NOT NULL, channel TEXT NOT NULL, status TEXT NOT NULL);
/* 3 sample rows of orders:
id | customer_id | branch_id | staff_id | ordered_at | channel | status
1 | 491 | 1 | 2 | 2026-01-01 08:06:28 | tại quầy | completed
2 | 384 | 1 | 4 | 2026-01-01 17:55:48 | grab | completed
3 | 576 | 2 | 7 | 2026-01-01 14:17:46 | tại quầy | completed */
CREATE TABLE order_items (
  id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), product_id INTEGER NOT NULL REFERENCES products(id),
  size TEXT NOT NULL, quantity INTEGER NOT NULL, unit_price INTEGER NOT NULL);
/* 3 sample rows of order_items:
id | order_id | product_id | size | quantity | unit_price
1 | 1 | 3 | M | 1 | 39000
2 | 2 | 2 | M | 3 | 42000
3 | 3 | 5 | L | 2 | 44000 */
CREATE TABLE suppliers (id INTEGER PRIMARY KEY, price INTEGER, product_id INTEGER, updated_at TEXT, amount INTEGER, status TEXT);
CREATE TABLE purchase_orders (id INTEGER PRIMARY KEY, price INTEGER, note TEXT, branch_id INTEGER, staff_id INTEGER, quantity INTEGER);
CREATE TABLE inventory (id INTEGER PRIMARY KEY, note TEXT, customer_id INTEGER, branch_id INTEGER, product_id INTEGER, created_at TEXT);
CREATE TABLE inventory_moves (id INTEGER PRIMARY KEY, branch_id INTEGER, updated_at TEXT, staff_id INTEGER, price INTEGER, status TEXT);
CREATE TABLE ingredients (id INTEGER PRIMARY KEY, created_at TEXT, quantity INTEGER, updated_at TEXT, status TEXT, staff_id INTEGER);
CREATE TABLE recipes (id INTEGER PRIMARY KEY, amount INTEGER, customer_id INTEGER, price INTEGER, staff_id INTEGER, product_id INTEGER);
CREATE TABLE equipment (id INTEGER PRIMARY KEY, amount INTEGER, status TEXT, name TEXT, updated_at TEXT, customer_id INTEGER);
CREATE TABLE maintenance_logs (id INTEGER PRIMARY KEY, note TEXT, name TEXT, product_id INTEGER, customer_id INTEGER, staff_id INTEGER);
CREATE TABLE shifts (id INTEGER PRIMARY KEY, updated_at TEXT, branch_id INTEGER, product_id INTEGER, note TEXT, status TEXT);
CREATE TABLE timesheets (id INTEGER PRIMARY KEY, created_at TEXT, note TEXT, quantity INTEGER, name TEXT, product_id INTEGER);
CREATE TABLE payroll (id INTEGER PRIMARY KEY, created_at TEXT, status TEXT, updated_at TEXT, product_id INTEGER, price INTEGER);
CREATE TABLE leave_requests (id INTEGER PRIMARY KEY, updated_at TEXT, note TEXT, amount INTEGER, created_at TEXT, price INTEGER);
CREATE TABLE promotions (id INTEGER PRIMARY KEY, price INTEGER, quantity INTEGER, amount INTEGER, name TEXT, note TEXT);
CREATE TABLE promotion_usage (id INTEGER PRIMARY KEY, note TEXT, status TEXT, customer_id INTEGER, product_id INTEGER, quantity INTEGER);
CREATE TABLE marketing_campaigns (id INTEGER PRIMARY KEY, price INTEGER, note TEXT, branch_id INTEGER, created_at TEXT, quantity INTEGER);
CREATE TABLE ad_spend (id INTEGER PRIMARY KEY, amount INTEGER, status TEXT, created_at TEXT, updated_at TEXT, note TEXT);
CREATE TABLE social_posts (id INTEGER PRIMARY KEY, quantity INTEGER, product_id INTEGER, customer_id INTEGER, status TEXT, amount INTEGER);
CREATE TABLE reviews (id INTEGER PRIMARY KEY, product_id INTEGER, note TEXT, quantity INTEGER, customer_id INTEGER, branch_id INTEGER);
CREATE TABLE complaints (id INTEGER PRIMARY KEY, note TEXT, price INTEGER, customer_id INTEGER, quantity INTEGER, status TEXT);
CREATE TABLE delivery_partners (id INTEGER PRIMARY KEY, product_id INTEGER, customer_id INTEGER, amount INTEGER, updated_at TEXT, branch_id INTEGER);
CREATE TABLE delivery_fees (id INTEGER PRIMARY KEY, branch_id INTEGER, price INTEGER, customer_id INTEGER, name TEXT, product_id INTEGER);
CREATE TABLE vouchers (id INTEGER PRIMARY KEY, customer_id INTEGER, amount INTEGER, quantity INTEGER, branch_id INTEGER, name TEXT);
CREATE TABLE gift_cards (id INTEGER PRIMARY KEY, product_id INTEGER, updated_at TEXT, name TEXT, staff_id INTEGER, price INTEGER);
CREATE TABLE utilities_bills (id INTEGER PRIMARY KEY, created_at TEXT, staff_id INTEGER, name TEXT, updated_at TEXT, branch_id INTEGER);
CREATE TABLE rent_contracts (id INTEGER PRIMARY KEY, branch_id INTEGER, staff_id INTEGER, quantity INTEGER, customer_id INTEGER, name TEXT);
CREATE TABLE audit_logs (id INTEGER PRIMARY KEY, branch_id INTEGER, amount INTEGER, name TEXT, staff_id INTEGER, updated_at TEXT);

Examples:
Câu hỏi: Có bao nhiêu khách hàng ở Đà Nẵng?
```sql
SELECT COUNT(*) FROM customers WHERE city = 'Đà Nẵng';
```
Câu hỏi: Doanh thu tháng 3/2026 của chi nhánh Mây Nguyễn Huệ là bao nhiêu?
```sql
SELECT SUM(i.quantity * i.unit_price) FROM order_items i JOIN orders o ON o.id = i.order_id
JOIN branches b ON b.id = o.branch_id
WHERE b.name = 'Mây Nguyễn Huệ' AND o.status = 'completed'
  AND o.ordered_at >= '2026-03-01' AND o.ordered_at < '2026-04-01';
```
Câu hỏi: Bao nhiêu ly Bạc xỉu size L đã bán trong tháng 5/2026?
```sql
SELECT SUM(i.quantity) FROM order_items i JOIN orders o ON o.id = i.order_id
JOIN products p ON p.id = i.product_id
WHERE p.name = 'Bạc xỉu' AND i.size = 'L' AND o.status = 'completed'
  AND o.ordered_at >= '2026-05-01' AND o.ordered_at < '2026-06-01';
```

Câu hỏi: Trong số khách hàng có ít nhất một đơn hoàn thành năm 2026, bao nhiêu phần trăm có từ 2 đơn hoàn thành trở lên?
